mockup.css:
.mock-hero-vertical-rail { display: grid; grid-template-columns: 9% 1fr; background: #f4f2ea; color: #14231c;
  font-family: "Iowan Old Style", Palatino, Georgia, serif; }
.mock-hero-vertical-rail .spine { background: #123a2c; color: #eef3ef; display: flex; align-items: center;
  justify-content: center; }
.mock-hero-vertical-rail .spine span { writing-mode: vertical-rl; transform: rotate(180deg);
  font-family: "Inter", ui-sans-serif, sans-serif; font-size: 1.5cqw;
  letter-spacing: .34em; text-transform: uppercase; }
.mock-hero-vertical-rail .field { display: grid; grid-template-columns: 1fr 38%; }
.mock-hero-vertical-rail .copy { padding: 6cqw 4cqw 5cqw 5cqw; display: flex; flex-direction: column;
  justify-content: center; gap: 2.6cqw; }
.mock-hero-vertical-rail h4 { margin: 0; font-size: 7.6cqw; line-height: .98; letter-spacing: -.02em; }
.mock-hero-vertical-rail p { margin: 0; font-family: "Inter", ui-sans-serif, sans-serif; font-size: 1.9cqw;
  line-height: 1.45; opacity: .78; max-width: 30ch; }
.mock-hero-vertical-rail .plate { margin: 5cqw 5cqw 5cqw 0; }
